const payoutsItems = `-- name: PayoutsItems :many
select pi.fulfilment_id, pi.amount_kobo, o.order_number, f.delivered_at
from finance.payout_items pi join sales.fulfilments f on f.id = pi.fulfilment_id join sales.orders o on o.id = f.order_id
where pi.payout_id = $1 order by f.delivered_at
`

type PayoutsItemsRow struct {
	FulfilmentID uuid.UUID  `json:"fulfilmentId"`
	AmountKobo   int64      `json:"amountKobo"`
	OrderNumber  string     `json:"orderNumber"`
	DeliveredAt  *time.Time `json:"deliveredAt"`
}

func (q *Queries) PayoutsItems(ctx context.Context, payoutID uuid.UUID) ([]PayoutsItemsRow, error) {
	rows, err := q.db.Query(ctx, payoutsItems, payoutID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PayoutsItemsRow{}
	for rows.Next() {
		var i PayoutsItemsRow
		if err := rows.Scan(
			&i.FulfilmentID,
			&i.AmountKobo,
			&i.OrderNumber,
			&i.DeliveredAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

